                        "position": {
                            "x": 16,
                            "y": 188,
                            "w": 536,
                            "h": 388
                        },
                        "type": "block"
                    },
                    {
                        "item": "viz_evidence_1_title",
                        "position": {
                            "x": 32,
                            "y": 200,
                            "w": 388,
                            "h": 36
                        },
                        "type": "block"
                    },
                    {
                        "item": "viz_evidence_1_description",
                        "position": {
                            "x": 32,
                            "y": 240,
                            "w": 504,
                            "h": 64
                        },
                        "type": "block"
                    },
                    {
                        "item": "viz_evidence_1_table",
                        "position": {
                            "x": 32,
